import { Component, computed, ElementRef, HostBinding, inject, input, Renderer2 } from '@angular/core';

class PctFiller {
  constructor() {
    Object.assign(this, { order: () => 2 });
  }
}

@Component({
  selector: 'pct-avatar',
  templateUrl: './avatar.html',
  host: {
    '[tabindex]': 'order()',
  },
})
export class PctAvatar extends PctFiller {
  protected readonly order!: () => number;
}
